-- ===== Equipment.LogStatus (EQUIP) =====
CREATE   PROCEDURE dbo.SP_POP_EQUIP_LogStatus
    @E VARCHAR(20),
    @L VARCHAR(20),
    @S VARCHAR(8),
    @R VARCHAR(30),
    @W INT,
    @By VARCHAR(20)
AS
