    ELSE IF @ProcessCode = 'PNT'
    BEGIN
    UPDATE dbo.PR_PntLot
    SET    ConfirmStatus = 'SCRAPPED', ConfirmedAt = SYSDATETIME(), ConfirmedBy = @Op,
           ModifiedBy = @Op, ModifiedTS = SYSDATETIME()
